INSERT INTO product_categories (name, slug, description, image_url, is_active) VALUES ('Planetary Mixers', 'planetary-mixers', 'EUROPYA and BCARE brand planetary mixers from 7 to 100 litre bowl capacity, built for bakeries, hotels and large-scale production kitchens.', '/products/europya-40-ltr-planetary-mixer/main.webp', true)
INSERT INTO product_categories (name, slug, description, image_url, is_active) VALUES ('Spiral Mixers & Dough Kneaders', 'spiral-mixers', 'Stainless steel fixed-bowl spiral mixers and automatic dough kneaders for consistent bread and bun dough development.', '/products/europya-spiral-mixer-8-kg/main.webp', true)
INSERT INTO product_categories (name, slug, description, image_url, is_active) VALUES ('Deck Ovens', 'deck-ovens', 'Automatic gas and electric deck ovens from single deck 1 tray up to 3 deck 9 tray, engineered for low fuel consumption.', '/products/europya-1-deck-1-tray-automatic-gas-oven/main.webp', true)
INSERT INTO product_categories (name, slug, description, image_url, is_active) VALUES ('Rotary Rack Ovens', 'rotary-rack-ovens', 'Trolley-based rotary rack ovens for high-volume, uniform baking across multiple trays.', '/products/single-trolley-rotary-rack-oven/main.webp', true)
INSERT INTO product_categories (name, slug, description, image_url, is_active) VALUES ('Bakery Equipment', 'bakery-equipment', 'Dough sheeters, proofers, bread slicers, icing machines and toasters supporting the complete bakery production line.', '/products/europya-dough-sheeter/main.webp', true)
INSERT INTO product_categories (name, slug, description, image_url, is_active) VALUES ('Commercial Kitchen Equipment', 'commercial-kitchen-equipment', 'Meat mincers, slicers, waffle machines and food preparation equipment for hotels, restaurants and cloud kitchens.', '/products/europya-meat-mincer/main.webp', true)
